const types = { '.js': 'text/javascript', '.mjs': 'text/javascript', '.wasm': 'application/wasm', '.glb': 'model/gltf-binary', '.html': 'text/html' };
http.createServer((req, res) => {
  const u = decodeURIComponent(req.url.split('?')[0]);
  let f = u.startsWith('/three/') ? path.join(THREE, u.slice(7)) : path.join(PUB, u);
  if (u === '/' ) f = path.join(path.dirname(process.argv[1]), 'harness.html');
