const fs = require('node:fs');
const path = require('node:path');
const file = process.argv[2];
const b = fs.readFileSync(file);
const len = b.readUInt32LE(12);
const json = JSON.parse(b.subarray(20, 20 + len).toString());
const bin = b.subarray(20 + len + 8);
const wasmBinary = fs.readFileSync(path.join(__dirname, 'draco_decoder.wasm'));
const mod = require(path.join(__dirname, 'draco_wasm_wrapper.js'));
mod({ wasmBinary }).then((decoder) => {
  let n = 0, pts = 0, faces = 0, fails = 0;
  for (const mesh of json.meshes) for (const prim of mesh.primitives) {
    const ext = prim.extensions && prim.extensions.KHR_draco_mesh_compression;
    if (!ext) continue;
    n++;
    const bv = json.bufferViews[ext.bufferView];
    const data = bin.subarray(bv.byteOffset || 0, (bv.byteOffset || 0) + bv.byteLength);
    const buf = new decoder.DecoderBuffer();
    buf.Init(new Int8Array(data.buffer, data.byteOffset, data.byteLength), data.byteLength);
    const dec = new decoder.Decoder();
    const type = dec.GetEncodedGeometryType(buf);
    const geom = type === decoder.TRIANGULAR_MESH ? new decoder.Mesh() : new decoder.PointCloud();
    const st = dec.DecodeBufferToMesh ? (type === decoder.TRIANGULAR_MESH ? dec.DecodeBufferToMesh(buf, geom) : dec.DecodeBufferToPointCloud(buf, geom)) : null;
    if (!st || !st.ok() || geom.ptr === 0) { fails++; }
    else { pts += geom.num_points(); faces += geom.num_faces(); }
    decoder.destroy(geom); decoder.destroy(dec); decoder.destroy(buf);
  }
  console.log(path.basename(file), { draco_prims: n, failed: fails, points: pts, faces });
});
EOF
